import {PRODUCTS,VEHICLE_CATEGORIES,vehicleCategory} from './model.mjs';
import {localizedPath,t,language,translateTree} from './i18n.mjs';
import {garmentPhoto} from '/apparel-ui.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const studioURL=id=>localizedPath('/satin/design-studio')+'?product='+id;
// Apparel appears in the studio as regular product cards; each opens a representative garment,
// and the garment style can be changed inside the designer (same group and category).
export const APPAREL_CARDS=[['T-Shirts','apparel-men-g500','Black'],['Long Sleeve Shirts','apparel-men-g540','Navy'],['Hoodies','apparel-men-g185','Sport Grey'],['Sweatshirts','apparel-men-g180','Maroon'],['Polos','apparel-men-88181','Royal'],['Tank Tops','apparel-men-g220','Red'],['Women’s T-Shirts','apparel-women-g500l','Heliconia'],['Kids T-Shirts','apparel-youth-g500b','Light Blue'],['Hats & Caps','apparel-hats-c130','Black'],['Totes','apparel-totes-q-tees-q800','Natural']].map(([name,id,colour])=>{const p=PRODUCTS.find(p=>p.id===id);const index=p?Math.max(0,p.garment.colors.indexOf(colour)):0;return p&&{name,id,colour:index,group:p.garment.group,category:p.garment.category};}).filter(Boolean);
export const apparelCardFor=product=>APPAREL_CARDS.find(c=>c.id===product?.id)||APPAREL_CARDS.find(c=>c.group===product?.garment?.group&&c.category===product?.garment?.category)||APPAREL_CARDS.find(c=>c.category===product?.garment?.category);
// Studio categories: the landing page shows these first; each opens its own product list (?cat=key).
const CATS=[
 {key:'print',name:'Print & marketing',d:'Business cards, flyers, postcards, brochures and door hangers.',ids:['business-cards','flyers','postcards','brochures','door-hangers'],cover:'business-cards'},
 {key:'signs',name:'Signs & real estate',d:'Real estate signs, yard signs and car magnets.',ids:['real-estate-signs','yard-signs','car-magnets'],cover:'real-estate-signs'},
 {key:'banners',name:'Banners & displays',d:'Roll-up and vinyl banners, X-frames, flags and A-frame signs.',ids:['roll-up-banner','vinyl-banners','x-frame-banner','flags','a-frame-signs'],cover:'roll-up-banner'},
 {key:'labels',name:'Labels & stickers',d:'Roll labels, sticker sheets and die-cut stickers in any shape and size.',ids:['roll-labels','sticker-sheets','die-cut-stickers'],cover:'roll-labels'},
 {key:'vehicles',name:'Vehicle wraps',d:'Sedans, vans, pickups, SUVs, trucks and trailers at real dimensions.'},
 {key:'apparel',name:'Apparel',d:'T-shirts, hoodies, polos, hats and totes — and oversize print T-shirts with a live 3D preview.'}];
const catURL=k=>localizedPath('/satin/design-studio')+'?cat='+k;
const chevron='<svg width="14" height="14" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m5 7 5 5 5-5" stroke="currentColor" stroke-width="1.5"/></svg>';
const productImage=p=>p.thumb||(p.id.startsWith('vehicle-')?'/studio/mockups/'+(p.id==='vehicle-pickup'?'pickup':p.id==='vehicle-minivan'?'minivan':'van')+'.png':'/satin/img/'+p.photo+'-480.webp');
// Vehicle bodies grouped by customer-facing category (SUV, pickup, van, minivan, box/step truck, trailer…); empty categories are left out.
// Within a category: drawn bodies before legacy photo bodies, and bodies of a product whose main category is another one last.
export function vehicleGroups(){const all=PRODUCTS.filter(p=>p.bodies).flatMap(p=>p.bodies.map(b=>({p,b,cat:vehicleCategory(b)})));const main=p=>{const n={};for(const b of p.bodies){const c=vehicleCategory(b);n[c]=(n[c]||0)+1;}return Object.entries(n).sort((a,b)=>b[1]-a[1])[0][0];};
 return VEHICLE_CATEGORIES.map(([key,label])=>({key,label,items:all.filter(x=>x.cat===key).map((x,i)=>({...x,i})).sort((x,y)=>(!!x.b.legacy-!!y.b.legacy)||((main(x.p)!==key)-(main(y.p)!==key))||x.i-y.i)})).filter(g=>g.items.length);}
export const bodyImage=(p,b)=>b.art?'/studio/mockups/'+b.art+'-thumb.webp':productImage({...p,thumb:''});
// Vehicle picker (studio home): category chips (All + one per category) over grouped grids; each card opens the studio on that body.
function vehiclePicker(){const groups=vehicleGroups(),total=groups.reduce((n,g)=>n+g.items.length,0),want=new URLSearchParams(location.search).get('type'),cur=groups.some(g=>g.key===want)?want:'all';
 const chip=(key,label,n)=>`<button type="button" class="cv-chip ${cur===key?'on':''}" data-vehicle-filter="${key}" aria-pressed="${cur===key}">${esc(t(label))} <span class="cv-chip-n">${n}</span></button>`;
 return `<div class="studio-vcats cv-tpl-cats" role="group" aria-label="${esc(t('Vehicle categories'))}">${chip('all','All',total)}${groups.map(g=>chip(g.key,g.label,g.items.length)).join('')}</div>`+groups.map(g=>`<section data-vehicle-group="${g.key}" ${cur!=='all'&&cur!==g.key?'hidden':''}><h3 class="studio-picker-sub">${esc(t(g.label))}</h3><div class="studio-picker-grid">${g.items.map(({p,b})=>`<a href="${studioURL(p.id)}&body=${b.id}"><img src="${bodyImage(p,b)}" alt="" loading="lazy"><h3 data-no-translate>${esc(b.name)}</h3><span>Open designer</span></a>`).join('')}</div></section>`).join('');}
// Studio home, vehicles: the category chips filter the grouped list in place (and keep ?type= in the address for sharing / back).
export function bindVehicleFilter(root){const box=root.querySelector('.studio-picker-vehicles');if(!box)return ()=>{};const click=e=>{const b=e.target.closest('[data-vehicle-filter]');if(!b)return;const key=b.dataset.vehicleFilter;box.querySelectorAll('[data-vehicle-filter]').forEach(x=>{const on=x===b;x.classList.toggle('on',on);x.setAttribute('aria-pressed',on);});box.querySelectorAll('[data-vehicle-group]').forEach(g=>g.hidden=key!=='all'&&g.dataset.vehicleGroup!==key);const u=new URL(location.href);if(key==='all')u.searchParams.delete('type');else u.searchParams.set('type',key);history.replaceState(history.state,'',u.pathname+u.search);};box.addEventListener('click',click);return ()=>box.removeEventListener('click',click);}
function entries(cat){const c=typeof cat==='string'?CATS.find(x=>x.key===cat):cat;if(!c)return [];if(c.key==='apparel')return [{id:'aop-tshirt',name:'Oversize print T-shirt',image:'/studio/mockups/aop-tshirt-thumb.webp'},...APPAREL_CARDS.map(a=>({id:a.id,name:a.name,image:garmentPhoto(a.id,a.colour),apparel:true}))];if(c.key==='vehicles')return PRODUCTS.filter(p=>p.bodies).map(p=>({id:p.id,name:p.name,image:productImage(p)}));return c.ids.map(id=>PRODUCTS.find(p=>p.id===id)).filter(Boolean).map(p=>({id:p.id,name:p.name,image:productImage(p)}));}
function catImage(c){if(c.key==='apparel'){const a=APPAREL_CARDS[0];return a?garmentPhoto(a.id,a.colour):'';}if(c.key==='vehicles')return '/studio/mockups/vehicles/p/sprinter-144-high-thumb.webp';const p=PRODUCTS.find(p=>p.id===c.cover);return p?productImage(p):'';}
function catCount(c){return c.key==='vehicles'?PRODUCTS.filter(p=>p.bodies).reduce((n,p)=>n+p.bodies.length,0):c.key==='apparel'?PRODUCTS.filter(p=>p.group==='Apparel').length+1:entries(c).length;}
function links(group,selected){const card=selected.startsWith('apparel-')?apparelCardFor(PRODUCTS.find(p=>p.id===selected))?.id:selected;return entries(group).map(p=>`<a href="${studioURL(p.id)}" ${p.id===card?'aria-current="page"':''}>${esc(t(p.name))}</a>`).join('');}
export function studioNavigation(selected=''){return `<nav class="studio-navigation" aria-label="${esc(t('Studio product menu'))}"><a class="studio-nav-home" href="${localizedPath('/satin/design-studio')}">${esc(t('All products'))}</a>${CATS.map(c=>`<details class="studio-nav-group"><summary>${esc(t(c.name))}${chevron}</summary><div class="studio-mega"><div class="studio-mega-intro"><span>${esc(t('Design Studio'))}</span><h2>${esc(t(c.name))}</h2><a href="${catURL(c.key)}">${esc(t('See all'))} →</a></div><div class="studio-mega-links">${links(c.key,selected)}</div></div></details>`).join('')}</nav>`;}
export function studioPicker(){const key=new URLSearchParams(location.search).get('cat'),cat=CATS.find(c=>c.key===key);
 const head=(title,sub,crumb)=>`<header class="studio-head"><div>${crumb||'<span class="studio-eyebrow">SATIN GRAPHIC DESIGN STUDIO</span>'}<h1>${esc(t(title))}</h1><p>${esc(t(sub))}</p></div></header>`;
 const steps=`<ol class="studio-steps"><li class="current"><b>1</b><span>Choose product</span></li><li><b>2</b><span>Create your design</span></li><li><b>3</b><span>Review & save</span></li></ol>`;
 if(!cat)return `<div class="print-studio studio-picker">${studioNavigation()}${head('What would you like to design?','Choose a category, then the product you want to design.')}${steps}<div class="studio-cats">${CATS.map(c=>`<a class="studio-cat" href="${catURL(c.key)}"><span class="studio-cat-img"><img src="${catImage(c)}" alt="" loading="lazy"></span><span class="studio-cat-text"><b>${esc(t(c.name))}</b><small>${esc(t(c.d))}</small><em>${catCount(c)} ${esc(t(c.key==='vehicles'?'vehicle models':'products'))} →</em></span></a>`).join('')}</div></div>`;
 const crumb=`<nav class="studio-crumb"><a href="${localizedPath('/satin/design-studio')}">${esc(t('All categories'))}</a><span>/</span><span>${esc(t(cat.name))}</span></nav>`;
 const body=cat.key==='vehicles'?`<section class="studio-picker-section studio-picker-vehicles">${vehiclePicker()}</section>`:`<section class="studio-picker-section"><div class="studio-picker-grid">${entries(cat).map(p=>`<a href="${studioURL(p.id)}" ${p.apparel?'class="studio-apparel-card"':''}><img src="${p.image}" alt="${esc(t(p.name))}" loading="lazy"><h3>${esc(t(p.name))}</h3><span>Open designer</span></a>`).join('')}</div></section>`;
 return `<div class="print-studio studio-picker">${studioNavigation()}${head(cat.name,cat.d,crumb)}${steps}${body}<p class="studio-cat-back"><a href="${localizedPath('/satin/design-studio')}">← ${esc(t('All categories'))}</a></p></div>`;}
// Closes menus reliably and always navigates with a full page load, so the editor never keeps the previous product.
export function bindStudioNavigation(root,beforeNavigate){const nav=root.querySelector('.studio-navigation');if(!nav)return ()=>{};const groups=[...nav.querySelectorAll('details')];const close=()=>groups.forEach(g=>g.open=false);const click=e=>{if(!nav.contains(e.target))close();};const key=e=>{if(e.key==='Escape'){const open=groups.find(g=>g.open);close();open?.querySelector('summary').focus();}if(e.key==='ArrowDown'&&e.target.matches('.studio-nav-group>summary')){e.preventDefault();e.target.parentElement.open=true;e.target.parentElement.querySelector('a')?.focus();}};const shown=e=>{if(e.persisted)close();};groups.forEach(g=>g.addEventListener('toggle',()=>{if(g.open)groups.filter(o=>o!==g).forEach(o=>o.open=false);}));nav.addEventListener('keydown',key);document.addEventListener('pointerdown',click);window.addEventListener('pageshow',shown);
 let leaving=false;const go=async e=>{const a=e.target.closest('a');if(!a||e.defaultPrevented||e.button>0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();e.stopPropagation();close();if(leaving)return;leaving=true;try{if(beforeNavigate&&await beforeNavigate(a.href)===false){leaving=false;return;}}catch{}location.assign(a.href);};nav.addEventListener('click',go);
 translateTree(nav);return ()=>{document.removeEventListener('pointerdown',click);window.removeEventListener('pageshow',shown);nav.removeEventListener('keydown',key);nav.removeEventListener('click',go);};}
